package net.minecraft.item; import net.minecraft.nbt.CompoundNBT; public class ItemStack { public static final ItemStack EMPTY = new ItemStack(null,0); private final Item item; private int count; public ItemStack(Item i,int c){item=i;count=c;} public boolean isEmpty(){return this==EMPTY || item==null || count<=0;} public Item getItem(){return item;} public int getCount(){return count;} public int getMaxStackSize(){return 64;} public int getDamage(){return 0;} public ItemStack copy(){return new ItemStack(item,count);} public static boolean areItemStackTagsEqual(ItemStack a, ItemStack b){return true;} public static ItemStack read(CompoundNBT tag){return EMPTY;} public CompoundNBT write(CompoundNBT tag){return tag;} }
